import java.util.ArrayList;
import java.util.List;

import org.springframework.stereotype.Service;

/**
 * Keeps the messages sent so far in memory, shared by all sessions.
 */
@Service
public class ContactMessageService {

    private final List<ContactMessage> messages = new ArrayList<>();

    public synchronized void add(ContactMessage message) {
        messages.addFirst(message);
    }

    /**
     * @return a snapshot of all messages, newest first
     */
    public synchronized List<ContactMessage> findAll() {
        return List.copyOf(messages);
    }
}
