+package com.example.contact;
+
+import java.util.List;
+import java.util.regex.Pattern;
+
+import com.example.about.AboutView;
+import com.vaadin.flow.component.HasValidation;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.Shortcuts;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.button.ButtonVariant;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.formlayout.FormLayout;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.component.textfield.TextFieldBase;
+import com.vaadin.flow.data.validator.EmailValidator;
+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveEvent.ContinueNavigationAction;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+@PageTitle("Contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final int MAX_MESSAGE_LENGTH = 500;
+
+    private final ContactMessageService messages;
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final List<TextFieldBase<?, String>> inputs = List.of(name, email, phone, message);
+
+    private final Button send = new Button("Send", e -> submit());
+    private final Grid<ContactMessage> grid = new Grid<>();
+
+    private final Dialog unsavedDialog = new Dialog();
+    private ContinueNavigationAction pendingNavigation;
+
+    public ContactView(ContactMessageService messages) {
+        this.messages = messages;
+
+        // The rules in validate() decide what is valid, not the field's own e-mail check.
+        email.setManualValidation(true);
+        inputs.forEach(input -> {
+            input.setValueChangeMode(ValueChangeMode.EAGER);
+            input.addValueChangeListener(e -> send.setEnabled(true));
+        });
+
+        send.addThemeVariants(ButtonVariant.LUMO_PRIMARY);
+        // Listen on the UI rather than the view, so Enter works whichever field has focus.
+        Shortcuts.addShortcutListener(this, this::submitOnEnter, Key.ENTER)
+                .listenOn(UI.getCurrent());
+
+        grid.addColumn(ContactMessage::name).setHeader("Name").setAutoWidth(true);
+        grid.addColumn(ContactMessage::email).setHeader("Email").setAutoWidth(true);
+        grid.addColumn(ContactMessage::phone).setHeader("Phone").setAutoWidth(true);
+        grid.addColumn(ContactMessage::message).setHeader("Message").setFlexGrow(1);
+        grid.setItems(messages.findAll());
+        grid.setHeight("24rem");
+
+        FormLayout form = new FormLayout(name, email, phone, message);
+        form.setResponsiveSteps(new FormLayout.ResponsiveStep("0", 1), new FormLayout.ResponsiveStep("40em", 2));
+        form.setColspan(message, 2);
+
+        unsavedDialog.setHeaderTitle("Discard your message?");
+        unsavedDialog.add("Your message has not been sent. Leaving this page now loses what you typed.");
+        Button keepEditing = new Button("Keep editing", e -> {
+            pendingNavigation = null;
+            unsavedDialog.close();
+        });
+        Button discard = new Button("Discard", e -> {
+            unsavedDialog.close();
+            pendingNavigation.proceed();
+        });
+        discard.addThemeVariants(ButtonVariant.LUMO_ERROR);
+        unsavedDialog.getFooter().add(keepEditing, discard);
+
+        add(new H1("Contact"), new RouterLink("About", AboutView.class), form, send, grid, unsavedDialog);
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (hasUnsentInput()) {
+            pendingNavigation = event.postpone();
+            unsavedDialog.open();
+        }
+    }
+
+    private void submitOnEnter() {
+        // The leave dialog is a child of this view, so the shortcut still fires while it is open.
+        if (send.isEnabled() && !unsavedDialog.isOpened()) {
+            submit();
+        }
+    }
+
+    private void submit() {
+        if (!validate()) {
+            return;
+        }
+        messages.add(new ContactMessage(
+                name.getValue().trim(),
+                email.getValue().trim(),
+                phone.getValue().trim(),
+                message.getValue().trim()));
+        Notification.show("Message sent");
+        // Clearing fires the value change listeners, which enable Send,
+        // so Send is disabled only after the fields are empty.
+        inputs.forEach(input -> input.clear());
+        send.setEnabled(false);
+        grid.setItems(messages.findAll());
+    }
+
+    /**
+     * Checks every rule, so each failing field shows its own error.
+     *
+     * @return true if the form can be sent
+     */
+    private boolean validate() {
+        String nameError = name.getValue().isBlank() ? "Name is required" : null;
+        String emailError = emailError();
+        String messageError = messageError();
+
+        markInvalid(name, nameError);
+        markInvalid(email, emailError);
+        markInvalid(message, messageError);
+
+        return nameError == null && emailError == null && messageError == null;
+    }
+
+    private String emailError() {
+        String address = email.getValue().trim();
+        if (!address.isEmpty()) {
+            return Pattern.matches(EmailValidator.PATTERN, address) ? null : "Enter a valid e-mail address";
+        }
+        return phone.getValue().isBlank() ? "Give an e-mail address or a phone number" : null;
+    }
+
+    private String messageError() {
+        String text = message.getValue().trim();
+        if (text.isEmpty()) {
+            return "Message is required";
+        }
+        if (text.codePointCount(0, text.length()) > MAX_MESSAGE_LENGTH) {
+            return "Message must be at most " + MAX_MESSAGE_LENGTH + " characters";
+        }
+        return null;
+    }
+
+    private static void markInvalid(HasValidation field, String error) {
+        field.setInvalid(error != null);
+        field.setErrorMessage(error);
+    }
+
+    private boolean hasUnsentInput() {
+        return inputs.stream().anyMatch(input -> !input.getValue().isBlank());
+    }
+}
