+import org.springframework.boot.test.context.SpringBootTest;
+
+/**
+ * The message list lives in a Spring singleton, so these tests never count
+ * rows; they look at the newest row, which is the one each test has just sent.
+ */
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    @Test
+    void showsHeadingAndAboutLink() {
+        navigate(ContactView.class);
+
+        $(H1.class).withText("Contact").single();
+        $(RouterLink.class).withText("About").single();
+    }
+
+    @Test
+    void untouchedFormIsEmptyAndSendIsEnabled() {
+        navigate(ContactView.class);
+
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void emptySubmitMarksEachFailingFieldAndSendsNothing() {
+        navigate(ContactView.class);
+
+        test(send()).click();
+
+        assertTrue(name().isInvalid());
+        assertEquals("Name is required", name().getErrorMessage());
+        assertTrue(email().isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email().getErrorMessage());
+        assertFalse(phone().isInvalid());
+        assertTrue(message().isInvalid());
+        assertEquals("Message is required", message().getErrorMessage());
+        assertEquals(0, $(Notification.class).all().size());
+    }
+
+    @Test
+    void invalidEmailIsRejectedAndInputIsKept() {
+        navigate(ContactView.class);
+        typeInto(name(), "Invalid Email");
+        typeInto(email(), "not-an-email");
+        typeInto(message(), "Hello");
+
+        test(send()).click();
+
+        assertTrue(email().isInvalid());
+        assertEquals("Enter a valid e-mail address", email().getErrorMessage());
+        assertFalse(name().isInvalid());
+        assertFalse(message().isInvalid());
+        assertEquals("not-an-email", email().getValue());
+        assertEquals("Hello", message().getValue());
+        assertEquals(0, $(Notification.class).all().size());
+    }
+
+    @Test
+    void phoneAloneIsEnoughAndEmailAloneIsEnough() {
+        navigate(ContactView.class);
+        typeInto(name(), "Phone Only");
+        typeInto(phone(), "+358 40 123 4567");
+        typeInto(message(), "Call me");
+        test(send()).click();
+        assertEquals("Phone Only", firstRowName());
+
+        typeInto(name(), "Email Only");
+        typeInto(email(), "email.only@example.com");
+        typeInto(message(), "Write to me");
+        test(send()).click();
+        assertEquals("Email Only", firstRowName());
+        assertFalse(email().isInvalid());
+    }
+
+    @Test
+    void messageLengthIsCheckedAgainstTheLimit() {
+        navigate(ContactView.class);
+        typeInto(name(), "Too Long");
+        typeInto(email(), "long@example.com");
+        typeInto(message(), "a".repeat(501));
+
+        test(send()).click();
+
+        assertTrue(message().isInvalid());
+        assertEquals("Message must be at most 500 characters", message().getErrorMessage());
+
+        typeInto(message(), "b".repeat(500));
+        test(send()).click();
+
+        assertFalse(message().isInvalid());
+        assertEquals("Too Long", firstRowName());
+    }
+
+    @Test
+    void validSubmitShowsNotificationAddsRowAndClearsFields() {
+        navigate(ContactView.class);
+        typeInto(name(), "Alice Sender");
+        typeInto(email(), "alice@example.com");
+        typeInto(phone(), "123");
+        typeInto(message(), "Hello there");
+
+        test(send()).click();
+
+        NotificationTester<Notification> notification = test($(Notification.class).single());
+        assertTrue(notification.getText().contains("Message sent"));
+        assertEquals("Alice Sender", firstRowName());
+        assertEquals("Hello there", firstRowMessage());
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+    }
+
+    @Test
+    void sendIsDisabledAfterSendingUntilTheNextEdit() {
+        navigate(ContactView.class);
+        typeInto(name(), "Dana");
+        typeInto(phone(), "555");
+        typeInto(message(), "First");
+        test(send()).click();
+
+        assertEquals("Dana", firstRowName());
+        assertFalse(send().isEnabled());
+
+        typeInto(phone(), "555");
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void enterSendsTheMessageWhenTheFormIsValid() {
+        navigate(ContactView.class);
+        typeInto(name(), "Enter Key");
+        typeInto(phone(), "777");
+        typeInto(message(), "Sent with enter");
+
+        fireShortcut(Key.ENTER);
+
+        assertEquals("Enter Key", firstRowName());
+        assertEquals("", message().getValue());
+    }
+
+    @Test
+    void enterOnAnInvalidFormSendsNothing() {
+        navigate(ContactView.class);
+        typeInto(name(), "");
+        typeInto(message(), "Missing contact details");
+        int before = rowCount();
+
+        fireShortcut(Key.ENTER);
+
+        assertTrue(name().isInvalid());
+        assertEquals(before, rowCount());
+    }
+
+    @Test
+    void enterDoesNothingWhileSendIsDisabled() {
+        navigate(ContactView.class);
+        typeInto(name(), "Eve");
+        typeInto(phone(), "444");
+        typeInto(message(), "Once only");
+        test(send()).click();
+        int before = rowCount();
+
+        fireShortcut(Key.ENTER);
+
+        assertEquals(before, rowCount());
+        assertFalse(name().isInvalid());
+        assertFalse(message().isInvalid());
+    }
+
+    @Test
+    void sentMessagesAreStillListedAfterLeavingAndComingBack() {
+        navigate(ContactView.class);
+        typeInto(name(), "Persistent Pat");
+        typeInto(phone(), "999");
+        typeInto(message(), "Remember me");
+        test(send()).click();
+
+        test($(RouterLink.class).withText("About").single()).click();
+        assertInstanceOf(AboutView.class, getCurrentView());
+
+        navigate(ContactView.class);
+
+        assertEquals("Persistent Pat", firstRowName());
+        assertEquals("Remember me", firstRowMessage());
+    }
+
+    @Test
+    void leavingWithInputAsksFirstAndKeepEditingStaysOnTheView() {
+        navigate(ContactView.class);
+        typeInto(name(), "Unsaved Uma");
+
+        test($(RouterLink.class).withText("About").single()).click();
+
+        Dialog dialog = $(Dialog.class).single();
+        assertTrue(dialog.isOpened());
+        assertInstanceOf(ContactView.class, getCurrentView());
+
+        test($(Button.class).withText("Keep editing").single()).click();
+
+        assertFalse(dialog.isOpened());
+        assertInstanceOf(ContactView.class, getCurrentView());
+        assertEquals("Unsaved Uma", name().getValue());
+    }
+
+    @Test
+    void discardingFromTheDialogGoesToAbout() {
+        navigate(ContactView.class);
+        typeInto(message(), "Throw this away");
+
+        test($(RouterLink.class).withText("About").single()).click();
+        test($(Button.class).withText("Discard").single()).click();
+
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertEquals("About", $(H1.class).single().getText());
+    }
+
+    @Test
+    void leavingAnEmptyFormDoesNotAskAnything() {
+        navigate(ContactView.class);
+
+        test($(RouterLink.class).withText("About").single()).click();
+
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertEquals(0, $(Dialog.class).all().size());
+    }
+
+    @Test
+    void aboutViewHasItsHeading() {
+        navigate(AboutView.class);
+
+        $(H1.class).withText("About").single();
+    }
+
+    private TextField name() {
+        return $(TextField.class).withLabel("Name").single();
+    }
+
+    private TextField phone() {
+        return $(TextField.class).withLabel("Phone").single();
+    }
+
+    private EmailField email() {
+        return $(EmailField.class).single();
+    }
+
+    private TextArea message() {
+        return $(TextArea.class).single();
+    }
+
+    private Button send() {
+        return $(Button.class).withText("Send").single();
+    }
+
+    private Grid<ContactMessage> grid() {
+        return $(Grid.class).single();
+    }
+
+    private int rowCount() {
+        return (int) grid().getListDataView().getItems().count();
+    }
+
+    private String firstRowName() {
+        return grid().getListDataView().getItems().findFirst().orElseThrow().name();
+    }
+
+    private String firstRowMessage() {
+        return grid().getListDataView().getItems().findFirst().orElseThrow().message();
+    }
+
+    private void typeInto(TextField field, String value) {
+        TextFieldTester<TextField, String> tester = test(field);
+        tester.setValue(value);
+    }
+
+    private void typeInto(EmailField field, String value) {
+        TextFieldTester<EmailField, String> tester = test(field);
+        tester.setValue(value);
+    }
+
+    private void typeInto(TextArea field, String value) {
+        TextAreaTester<TextArea> tester = test(field);
+        tester.setValue(value);
+    }
+}
